// Получить слово по ID
function getWordById(id) {
  return WORDS.find(w => w.id === id);
}

// Получить слова по категории
function getWordsByCategory(cat) {
  return WORDS.filter(w => w.cat === cat);
}

// Получить все категории
function getCategories() {
  return [...new Set(WORDS.map(w => w.cat))];
}

// Получить слова для сегодняшнего урока (по SRS)
function getDailyWords(progress, count = 20) {
  const today = new Date().toDateString();
  const due = WORDS.filter(w => {
    const p = progress[w.id];
    if (!p) return true; // новое слово
    return new Date(p.nextReview).toDateString() <= today;
  });
  return due.slice(0, count);
}
